const enfermedadData=[{"disease":"La prueba salía en verde y no comprobaba absolutamente nada","characteristic":"La lista llegaba vacía y nadie comprobó que hubiera algo que comprobar","opts":["La lista llegaba vacía y nadie comprobó que hubiera algo que comprobar","La prueba estaba mal escrita","Se ejecutó en el navegador equivocado","Faltaban comprobaciones"]},{"disease":"La sonda decía partir de cero y arrastraba el estado anterior","characteristic":"Borraba una clave con un nombre que no existe, y borrar lo que no hay no da error","opts":["Borraba una clave con un nombre que no existe, y borrar lo que no hay no da error","El navegador no permitía borrar","Se ejecutó dos veces","Faltaba recargar la página"]},{"disease":"Un dato existía en la aplicación y desde fuera salía indefinido","characteristic":"Se leía por la ventana, y una constante no se cuelga de ahí","opts":["Se leía por la ventana, y una constante no se cuelga de ahí","El archivo no estaba cargado","El nombre estaba mal escrito","Faltaba esperar más tiempo"]},{"disease":"Una herramienta funcionó en cinco misiones y falló en la sexta","characteristic":"Buscaba por el nombre de un parámetro que se había renombrado","opts":["Buscaba por el nombre de un parámetro que se había renombrado","La sexta misión era más grande","Se ejecutó con prisa","El archivo estaba corrupto"]},{"disease":"La ficha salió con una tabla abierta en una hoja y cerrada en otra","characteristic":"El corte cayó dentro de la tabla y la herramienta solo sabía retroceder sobre otro bloque","opts":["El corte cayó dentro de la tabla y la herramienta solo sabía retroceder sobre otro bloque","La tabla era demasiado larga","Se midió mal la página","Faltaba cerrar la etiqueta a mano"]},{"disease":"Volvió un fallo que ya se había arreglado la semana pasada","characteristic":"Se reescribió el archivo entero y el arreglo viejo no estaba en la versión nueva","opts":["Se reescribió el archivo entero y el arreglo viejo no estaba en la versión nueva","El arreglo estaba mal hecho","Alguien lo borró a propósito","El navegador guardó una copia vieja"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Hace lo que pediste en el caso que probaste.","type":"Funciona"},{"s":"Hace lo que pediste, no rompe nada más y se puede deshacer.","type":"Está bien"},{"s":"Qué archivos tocó de verdad el cambio.","type":"El alcance"},{"s":"Las líneas que desaparecieron sin que nadie lo pidiera.","type":"El borrado silencioso"},{"s":"Una librería nueva que llegó con el código.","type":"La dependencia"},{"s":"Sin señal, lista vacía, teléfono viejo, nombre con acento.","type":"El caso que decide"},{"s":"Una comprobación que no se ha visto en rojo nunca.","type":"La prueba que nunca falló"},{"s":"Ponerla dentro de la herramienta que produce la cosa.","type":"La comprobación"},{"s":"Un cambio por vez, con su mensaje diciendo el porqué.","type":"Deshacer"},{"s":"Recorrerla siempre devuelve que todos cumplen.","type":"La lista vacía"}];
const classifyTaskDB=[{"w":"Se ejecutó sin dar error","gen":"Estado del cambio","n":"Solo el caso fácil","g":"Funciona","t":"No dice nada más"},{"w":"Lo puedo explicar línea por línea","gen":"Estado del cambio","n":"Se puede sostener","g":"Está bien","t":"Se puede arreglar de noche"},{"w":"Qué líneas desaparecieron","gen":"Dónde se ve","n":"Solo en el cambio","g":"Se ve en el cambio","t":"Aquí vive lo caro"},{"w":"Si la estructura general encaja","gen":"Dónde se ve","n":"Hay que leer entero","g":"Se ve leyendo","t":"Otra revisión, otro momento"},{"w":"La maestra sin internet","gen":"Caso de prueba","n":"Incómodo","g":"Caso que decide","t":"Es el que hay que probar"},{"w":"Con señal y datos completos","gen":"Caso de prueba","n":"Cómodo","g":"Caso que luce","t":"Solo dice que no está roto del todo"},{"w":"La herramienta avisa si no encuentra algo","gen":"Efecto","n":"Se nota hoy","g":"Ayuda a revisar","t":"Cuesta una línea"},{"w":"La comprobación sale en verde a la primera","gen":"Efecto","n":"Se nota tarde","g":"Da falsa calma","t":"Hay que hacerla fallar"},{"w":"Un cambio pequeño por vez","gen":"Forma de subir","n":"Reversible","g":"Ayuda a revisar","t":"Se puede deshacer solo eso"},{"w":"Un archivo entero reescrito","gen":"Forma de subir","n":"Difícil de revisar","g":"Da falsa calma","t":"Aquí se cuela el borrado"}];
const completeTaskDB=[{"s":"Funciona no es lo mismo que ___ bien.","opts":["esta","suena","parece"],"ans":"esta"},{"s":"La revisión se hace mirando el ___, no el archivo.","opts":["cambio","resultado","mensaje"],"ans":"cambio"},{"s":"El fallo más caro es el borrado ___.","opts":["silencioso","evidente","parcial"],"ans":"silencioso"},{"s":"Una prueba que nunca se ha visto ___ no prueba nada.","opts":["fallar","ejecutar","escribir"],"ans":"fallar"},{"s":"El caso que hay que probar es el que da ___.","opts":["pereza","risa","orgullo"],"ans":"pereza"},{"s":"Una librería nueva es una decisión de ___.","opts":["arquitectura","estilo","formato"],"ans":"arquitectura"},{"s":"La comprobación se pone dentro de la ___ que produce la cosa.","opts":["herramienta","sonda","ficha"],"ans":"herramienta"},{"s":"La última red es poder ___.","opts":["deshacer","avisar","esperar"],"ans":"deshacer"}];
const explainQuestions=[{"q":"Explica por qué con el código la verificación se abandona antes que con el texto.","ans":"Porque el código no suena bien: funciona. Se ejecuta delante de ti, hace lo que pediste y no queda nada que sospechar, así que parece que ya se verificó solo. Con un texto uno sabe que hay que comprobar los datos; con un cambio que corre, la ejecución hace de comprobante falso. Y hay un agravante: cuando algo falla uno lo lee entero para arreglarlo, pero cuando funciona uno lo sube. Por eso la señal de alarma de esta etapa es «funcionó a la primera», que no es una buena noticia sino el momento de más riesgo, porque nada te obligó a mirar. La distinción que ordena todo es que funciona significa que hace lo que pediste en el caso que probaste, y está bien significa además que no rompe nada más, que se puede explicar y que se puede deshacer mañana."},{"q":"¿Por qué se revisa el cambio y no el archivo? Di qué se busca en cada parte.","ans":"Porque un archivo entero se lee y todo parece razonable, mientras que el cambio enseña exactamente qué se movió y qué desapareció. Se miran cuatro cosas. La lista de archivos tocados, para ver si hay alguno que no tenía por qué estar: ese es el primer aviso de que el alcance se fue de madre. Las líneas que desaparecen, que es donde vive el fallo más caro, porque nadie las pidió borrar. Las líneas que se añaden, para comprobar que se entiende cada una y que ninguna trae una dependencia nueva. Y lo que no cambió y debería: el comentario que ahora miente o la norma que quedó sin cumplir. De las cuatro, la segunda es la que casi nadie hace y la que más cuesta cuando se salta."},{"q":"Cuenta el caso de la prueba que salía en verde y di qué se aprendió.","ans":"Una sonda comprobaba que las ocho asignaciones tuvieran sus cinco partes, y las cinco comprobaciones salieron en verde a la primera. El código estaba bien escrito. Lo que pasaba es que la lista llegaba vacía, y recorrer una lista vacía preguntando si todos sus elementos cumplen algo devuelve que sí. Eran cinco comprobaciones perfectas sobre nada, dando permiso para seguir. Se aprendieron dos cosas. La primera, general: antes de creerle a una prueba hay que verla fallar una vez, porque una comprobación que nunca se ha visto en rojo no se sabe si funciona. La segunda, concreta y aburrida: cuando se comprueba una lista, lo primero es preguntar si hay algo que comprobar. El arreglo fue una línea."},{"q":"¿Qué es el borrado silencioso y por qué es el peor de los cinco fallos?","ans":"Es cuando la máquina reescribe un archivo entero y se lleva por delante un arreglo anterior, sin decir nada. No lo borra a propósito: reescribe desde lo que sabe, y lo que sabe no incluye tu última semana de trabajo. Es el peor de los cinco porque los otros cuatro se notan al probar (el caso fácil falla con datos raros, el alcance se ve en la lista de archivos, la dependencia se ve al principio del archivo y lo que no encaja con la casa salta a la vista), mientras que este no se nota: lo que se borró funcionaba y no lo estabas mirando. Se descubre semanas después, en otro sitio y sin relación aparente, cuando vuelve un fallo que ya se había arreglado. La defensa es mirar qué líneas desaparecen, pedir cambios pequeños en vez de archivos completos, y subir un cambio por vez."},{"q":"Explica por qué una herramienta que funcionó cinco veces puede fallar la sexta.","ans":"Porque funcionar no es estar probada: es estar probada en lo de siempre. En este proyecto hay un script que reescribe un trozo del molde en cada misión nueva, y funcionó en cinco misiones seguidas. Falló en la sexta porque buscaba ese trozo por el nombre de un parámetro, y en la misión anterior ese parámetro se había renombrado justamente para que dijera algo mejor. El mismo código, el mismo encargo, otro contexto. Lo que salvó la situación fue que la herramienta avisaba cuando no encontraba lo que buscaba, en vez de callarse y seguir: ese aviso cuesta una línea y es la diferencia entre notarlo el mismo día o dentro de un mes. La lección general es que el código correcto lo es para el contenido que había cuando se escribió, así que las herramientas tienen que quejarse cuando el mundo cambia."},{"q":"¿Dónde conviene poner una comprobación, y por qué? Da el ejemplo de las treinta preguntas.","ans":"Dentro de la herramienta que produce la cosa. Así no hay que acordarse de ejecutarla, no se puede saltar y falla en el momento exacto en que algo se rompe, no días después. El ejemplo de esta casa es un generador que crea una ficha desde el catálogo, y una de sus páginas tiene que llevar exactamente treinta preguntas. Trajo veintinueve. Nadie lo habría notado leyendo, porque veintinueve preguntas se ven igual que treinta y contarlas a mano es justo lo que nadie hace. Lo cazó una línea dentro del propio generador que cuenta y se niega a escribir el archivo si el número no cuadra. De los seis fallos reales que cuenta esta misión, ese es el único que no costó tiempo, y la diferencia fue solo dónde estaba puesta la comprobación."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

