function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una sonda nueva comprueba que las ocho asignaciones traigan sus cinco partes. Se ejecuta y salen cinco comprobaciones en verde a la primera."},{"txt":"Una sonda dice partir de cero borrando el estado guardado antes de medir. El código pide borrar una clave, y el nombre de la clave no coincide con el que usa la aplicación."},{"txt":"Una sonda lee el catálogo desde fuera con w.CATALOGO y le sale indefinido, aunque el archivo está cargado y bien escrito."},{"txt":"Un script reescribe un trozo del molde en cada misión nueva. Funcionó en cinco misiones seguidas y en la sexta no encuentra lo que busca, porque un parámetro se renombró."},{"txt":"La herramienta que reparte una ficha en diez páginas retrocede hasta el inicio de un bloque para no cortar por la mitad, pero solo sabe retroceder sobre un tipo de bloque."},{"txt":"Un generador crea una ficha desde el catálogo y una de sus páginas tiene que llevar exactamente treinta preguntas. Trae veintinueve."},{"txt":"Se pide una función para dar formato a fechas en español. Llega hecha, funciona, y su primera línea trae una librería nueva. El proyecto es estático y sin compilación."},{"txt":"Se pide arreglar una función y llega el archivo entero reescrito. La función arreglada funciona y todo lo demás se ve bien."}];
const critCaseQuestions=["1. ¿Qué mirarías de este cambio, y en qué orden?","2. ¿Con qué caso real lo probarías, aparte del fácil?","3. ¿Qué puede haber roto o borrado sin avisar?","4. Escribe en 3-4 frases si lo subirías, y qué comprobación dejarías puesta."];
const critCaseGuides=["El orden es siempre el mismo: la lista de archivos tocados, las líneas que desaparecen, las que se añaden, y lo que no cambió y debería. La segunda es la que casi nadie hace.","El caso real es el incómodo: sin señal, lista vacía, teléfono viejo, nombre con acento, dos personas a la vez. El que propone la máquina sirve solo para saber que no está roto del todo.","Lo que más se rompe sin avisar son los arreglos anteriores del mismo archivo, las convenciones de la casa y las cosas que dependían de un nombre que cambió.","La comprobación que se deja puesta vale más que el arreglo: se pone dentro de la herramienta que produce la cosa, y antes de confiar en ella se rompe algo a propósito para verla en rojo."];

const critErrorBank=[{"txt":"\"La sonda salió en verde a la primera, ya está lista\".","g1":"Verde a la primera es sospechoso, no tranquilizador: puede estar comprobando sobre una lista vacía, y recorrer una lista vacía siempre devuelve que todos cumplen.","g2":"Antes de confiar en ella hay que romper a propósito lo que debería detectar y verla en rojo. Y con listas, la comprobación que falta suele ser la más aburrida: ¿hay algo que comprobar?"},{"txt":"\"El código dice que borra el estado antes de medir, así que parte de cero\".","g1":"Dice que lo borra, y borrar algo que no existe no da error. Si el nombre de la clave no es el de la aplicación, no limpia nada y nadie se entera.","g2":"Se comprueba el efecto y no la intención: si algo dice que limpia, hay que mirar después que de verdad esté limpio."},{"txt":"\"Funcionó en las cinco misiones anteriores, no hace falta mirarlo\".","g1":"Funcionar no es estar probado: es estar probado en lo de siempre. Basta con que una palabra del contexto cambie para que deje de encontrar lo que busca.","g2":"Lo barato es que la herramienta avise cuando no encuentra su objetivo, en vez de callarse. Un aviso cuesta una línea y ahorra un mes de no enterarse."},{"txt":"\"Le pedí que arreglara la función y me reescribió el archivo entero, pero se ve bien\".","g1":"Ahí es donde vive el borrado silencioso: la máquina reescribe desde lo que sabe, y lo que sabe no incluye los arreglos de tu última semana.","g2":"Hay que mirar qué líneas desaparecen, no solo cuáles llegan. Y la defensa práctica es pedir cambios pequeños en vez de archivos completos."},{"txt":"\"Añadió una librería para las fechas, pero es la estándar y pesa poco\".","g1":"En un proyecto estático y sin compilación, cada librería es un archivo más que descargar, que cachear, que mantener y que puede caerse.","g2":"Eso no es una línea de código: es una decisión de arquitectura, y la toma quien conoce las decisiones del proyecto, no quien no las conoce."},{"txt":"\"La ficha salió bien, la miré y se ve correcta\".","g1":"Mirarla no basta cuando lo que falla no se ve: veintinueve preguntas se ven igual que treinta, y una tabla partida entre dos hojas puede pasar desapercibida.","g2":"Lo que caza esos fallos es una comprobación dentro de la herramienta que produce la ficha, que cuenta y se niega a escribir si el número no cuadra."}];

const critDecisionBank=["Una sonda nueva con cinco comprobaciones en verde a la primera: ¿se da por buena o qué se hace antes?","Un código que dice limpiar el estado antes de medir: ¿cómo se comprueba que de verdad limpia?","Un dato que existe en la aplicación y desde fuera sale indefinido: ¿cuál es la primera sospecha?","Una herramienta que funcionó cinco veces y falla la sexta: ¿se arregla la herramienta o se cambia otra cosa?","Un corte que partió una tabla entre dos hojas: ¿se arregla el corte o se añade una comprobación?","Un generador que trajo 29 preguntas en vez de 30: ¿dónde debería haber estado la comprobación?","Una librería nueva que llegó con la función pedida: ¿se acepta, se quita o depende?","Un archivo entero reescrito cuando se pidió arreglar una función: ¿qué se mira antes de subirlo?"];
const critDecisionGuide="La decisión correcta sigue las reglas de la casa: funciona no es lo mismo que está bien, así que lo primero es mirar el cambio y no el archivo, empezando por la lista de archivos tocados y siguiendo por las líneas que desaparecen; el código que no se puede explicar con palabras propias no se sube; se prueba el caso incómodo y no el que propone la máquina; una comprobación que nunca se ha visto en rojo no prueba nada, así que se rompe a propósito antes de confiar en ella; y la comprobación que se deja puesta va dentro de la herramienta que produce la cosa, para que no se pueda olvidar. Cuando hay prisa por subir, la respuesta es siempre la misma: un cambio por vez, con su mensaje, para poder deshacer.";

const critCompareBank=[{"a":"Pedir un cambio pequeño en una función concreta.","b":"Pedir el archivo entero reescrito y revisarlo después.","ga":"Caso A: el cambio se lee en un minuto, se ve qué desapareció y se puede deshacer solo eso si sale mal.","gb":"Caso B: todo parece razonable porque está escrito de nuevo, y ahí es exactamente donde se cuela el arreglo de la semana pasada que ya no está."},{"a":"Poner la comprobación dentro del generador que produce la ficha.","b":"Poner la comprobación en una sonda aparte que se ejecuta al final.","ga":"Caso A: no hay que acordarse, no se puede saltar, y falla en el momento exacto en que algo se rompe.","gb":"Caso B: sirve, pero solo si alguien se acuerda de ejecutarla, y el día con prisa es justo el día que no se ejecuta."},{"a":"Probar el caso de la maestra sin internet.","b":"Probar con buena señal y datos completos.","ga":"Caso A: prueba lo que de verdad se usa en el campo, que es donde el proyecto tiene que funcionar.","gb":"Caso B: dice que no está roto del todo. Es información, pero no es la que decide si se sube."},{"a":"Una herramienta que avisa cuando no encuentra lo que busca.","b":"Una herramienta que sigue en silencio si no lo encuentra.","ga":"Caso A: el fallo se nota el mismo día, cuesta una línea escribirlo y evita enterarse un mes después.","gb":"Caso B: parece que todo salió bien, y el trozo que tenía que cambiar se quedó como estaba sin que nadie lo sepa."}];

const critCauseBank=[{"cause":"Se toma «se ejecutó sin error» como prueba de que el cambio está bien.","guide":"Ejecutarse solo dice que funciona en el caso que probaste, que casi siempre es el fácil. No dice nada de lo que rompió ni de lo que borró."},{"cause":"Se revisa leyendo el archivo terminado.","guide":"Todo parece razonable, porque está escrito de corrido. Lo que desapareció no aparece en ningún sitio: solo se ve mirando qué cambió."},{"cause":"Se confía en una comprobación que nunca se ha visto en rojo.","guide":"No se sabe si funciona. Puede estar comprobando sobre una lista vacía, o mirando algo que ya no existe, y salir en verde igual."},{"cause":"Se prueba con el caso que propone la máquina.","guide":"Es el caso que hace lucir el código: datos completos, buena señal, un solo usuario. El que decide es el incómodo, y es el que da pereza montar."},{"cause":"Se acepta el archivo entero reescrito porque se ve bien.","guide":"Ahí vive el borrado silencioso: la máquina reescribe desde lo que sabe, y no sabe lo que arreglaste la semana pasada."},{"cause":"Se suben varios cambios juntos para ahorrar tiempo.","guide":"El día que uno falla no se puede deshacer solo ese, así que o se pierde todo o se pasa la tarde separando lo bueno de lo malo."}];
const critEffectBank=[{"effect":"Una sonda empezó a servir de verdad.","guide":"Se rompió a propósito lo que debía detectar y se la vio en rojo. Hasta entonces salía en verde sobre una lista vacía y no probaba nada."},{"effect":"Se descubrió el mismo día que una herramienta no había hecho su trabajo.","guide":"Avisaba cuando no encontraba lo que buscaba, en vez de callarse. El aviso costó una línea y ahorró un mes de no enterarse."},{"effect":"La ficha nunca volvió a salir con una tabla partida.","guide":"No se arregló la herramienta de cortar: se añadió una comprobación que cuenta tablas abiertas y cerradas. A veces el arreglo barato es notar el fallo."},{"effect":"No volvió un fallo que ya se había arreglado.","guide":"Se miraron las líneas que desaparecían antes que las que llegaban, y ahí estaba el arreglo viejo que el archivo reescrito no traía."},{"effect":"Un cambio que salió mal costó diez minutos y no una tarde.","guide":"Estaba subido solo, con su mensaje diciendo el porqué, así que se deshizo sin arrastrar nada de lo demás."},{"effect":"El proyecto siguió sin librerías nuevas durante todo el año.","guide":"Cada vez que llegó una de regalo se leyó la primera línea del archivo, y la decisión la tomó quien conoce las decisiones del proyecto."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Antes de subir · Forma ${cf} · La IA que programa · Ruta de la Máquina que Predice`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El cambio sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué mirarías de este cambio, con qué caso real lo probarías y qué puede haber borrado sin avisar? Explica por qué revisar el cambio es mejor que leer el archivo o que fiarse de que se ejecutó sin error.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos deja un cambio que se puede deshacer y defender mañana? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Antes de subir: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El cambio sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué mirarías de este cambio, con qué caso real lo probarías y qué puede haber borrado sin avisar? Explica por qué revisar el cambio es mejor que leer el archivo o que fiarse de que se ejecutó sin error.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos deja un cambio que se puede deshacer y defender mañana? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Antes de subir · La IA que programa · Ruta de la Máquina que Predice · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Antes de subir · La IA que programa · Ruta de la Máquina que Predice · Etapa 4 · Inteligencia Artificial</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Antes de subir · La IA que programa · Ruta de la Máquina que Predice · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"📖","label":"Lo entiendo","text":"Poder decir <strong>qué hace cada parte</strong>, con palabras propias. <strong>Sirve para:</strong> poder arreglarlo cuando falle. <strong>Si se salta:</strong> a las diez de la noche estás tú delante y la máquina no. <strong>La prueba:</strong> contarlo sin volver a mirarlo."},{"y":"2","icon":"🔍","label":"El alcance","text":"Qué archivos <strong>tocó de verdad</strong>. <strong>Sirve para:</strong> ver si se fue de madre. <strong>Si se salta:</strong> se cambian cosas que nadie pidió cambiar. <strong>Cómo:</strong> la lista de archivos modificados, uno por uno, antes de leer nada."},{"y":"3","icon":"🗑️","label":"El borrado","text":"Las líneas <strong>que desaparecen</strong>. <strong>Sirve para:</strong> cazar el fallo más caro. <strong>Si se salta:</strong> vuelve un problema arreglado hace semanas. <strong>Cómo:</strong> leer lo borrado antes que lo añadido, siempre."},{"y":"4","icon":"📦","label":"La dependencia","text":"Lo que <strong>llega de regalo</strong>: librerías, formatos, maneras nuevas. <strong>Sirve para:</strong> que la arquitectura la decidas tú. <strong>Si se salta:</strong> el proyecto engorda solo. <strong>Cómo:</strong> mirar las primeras líneas del archivo."},{"y":"5","icon":"🧪","label":"La prueba real","text":"El caso <strong>incómodo</strong>, no el que propone la máquina. <strong>Sirve para:</strong> saber si aguanta lo que de verdad pasa. <strong>Si se salta:</strong> funciona en tu teléfono y no en el de la maestra. <strong>Cómo:</strong> sin señal, lista vacía, aparato viejo."},{"y":"6","icon":"🛠️","label":"La comprobación","text":"Ponerla <strong>dentro de la herramienta</strong> que produce la cosa. <strong>Sirve para:</strong> que no se pueda olvidar ni saltar. <strong>Si se salta:</strong> se comprueba el día que hay tiempo, o sea nunca. <strong>Cómo:</strong> que se niegue a escribir si algo no cuadra."},{"y":"7","icon":"↩️","label":"Deshacer","text":"<strong>Un cambio por vez</strong>, con su mensaje. <strong>Sirve para:</strong> volver atrás sin arrastrar lo demás. <strong>Si se salta:</strong> un error se convierte en una tarde de arqueología. <strong>Cómo:</strong> subir poco y seguido, diciendo el porqué."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(laHaceFallar){sfx(laHaceFallar?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(laHaceFallar){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔴</span><span class="ms-text"><strong>La rompiste a propósito:</strong> le quitaste una parte a una asignación y la sonda siguió en verde. Ahí se vio.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✅</span><span class="ms-text"><strong>Y el arreglo fue una línea:</strong> preguntar primero si hay algo que comprobar. Ahora sí, cuando sale en verde significa algo.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🟢</span><span class="ms-text"><strong>La diste por buena:</strong> cinco comprobaciones en verde dan mucha tranquilidad.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🕳️</span><span class="ms-text"><strong>Y seguirá en verde para siempre:</strong> comprueba sobre una lista vacía. No avisará nunca, ni ahora ni el día que de verdad falte una parte.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"entiendo":{"nombre":"Lo entiendo","icon":"📖","estructura":{"title":"Qué es","info":"• Poder decir <strong>qué hace cada parte</strong> con palabras propias<br>• No es reconocerlo: es poder contarlo sin volver a mirarlo<br>• Es la misma prueba de la etapa 3, aplicada al código"},"funcion":{"title":"Cómo se hace","info":"• Se lee el cambio entero antes de tocar nada<br>• Se explica en voz alta, como si hubiera alguien delante<br>• Lo que no se pueda explicar <strong>se pregunta o se quita</strong>"},"enfermedades":{"title":"Qué pasa si se salta","info":"• El día que falle no se sabe por dónde empezar<br>• Se acumula código propio que nadie del proyecto entiende<br>• Y a las diez de la noche estás tú delante, no la máquina"},"cuidados":{"title":"En este proyecto","info":"• La regla: <strong>el código que no entiendes no se sube</strong><br>• Vale también para lo copiado de otra misión<br>• Y para las herramientas de <code>_dev/</code>, que son las que más duran"}},"alcance":{"nombre":"El alcance","icon":"🔍","estructura":{"title":"Qué es","info":"• Qué archivos <strong>tocó de verdad</strong> el cambio<br>• No los que dijo que iba a tocar: los que aparecen en la lista<br>• Es el primer aviso de que algo se fue de madre"},"funcion":{"title":"Cómo se hace","info":"• Se mira <strong>la lista de archivos modificados</strong> antes de leer nada<br>• Se pregunta por cada uno: ¿este tenía que estar aquí?<br>• Después se leen <strong>las líneas borradas</strong>, y solo luego las añadidas"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Se cambian cosas que nadie pidió cambiar<br>• Y se descubre semanas después, en un sitio sin relación<br>• Es el fallo que más veces ha pasado en esta casa"},"cuidados":{"title":"En este proyecto","info":"• Una herramienta de reparto reescribió <strong>las 21 misiones</strong> de una pasada<br>• Su informe salía en verde: solo hablaba de lo que venía a arreglar<br>• La comprobación buena no era leer el informe: era <strong>mirar la lista</strong>"}},"prueba":{"nombre":"La prueba","icon":"🧪","estructura":{"title":"Qué es","info":"• Ejecutar el <strong>caso que decide</strong>, no el que luce<br>• Sin señal, lista vacía, teléfono viejo, nombre con acento<br>• El que da pereza montar es justo el que hay que montar"},"funcion":{"title":"Cómo se hace","info":"• Se escribe el caso incómodo <strong>antes</strong> de mirar si funciona<br>• Se rompe a propósito lo que la comprobación debe detectar<br>• Y se mira que se ponga <strong>en rojo</strong>: si no, no sirve"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Funciona en tu teléfono y no en el de la maestra<br>• Las comprobaciones salen en verde sobre listas vacías<br>• Y el verde da permiso para seguir, que es lo peligroso"},"cuidados":{"title":"En este proyecto","info":"• Las sondas se escriben <strong>mirando primero que fallen</strong><br>• Una salió en verde comprobando <strong>una lista vacía</strong><br>• El arreglo fue una línea: preguntar si hay algo que comprobar"}},"deshacer":{"nombre":"Deshacer","icon":"↩️","estructura":{"title":"Qué es","info":"• Poder <strong>volver a lo que funcionaba</strong> sin arrastrar nada más<br>• Es la última defensa, la que actúa cuando todo lo demás falló<br>• Y la única que no depende de haber acertado"},"funcion":{"title":"Cómo se hace","info":"• <strong>Un cambio por vez</strong>, no cinco cosas juntas<br>• Cada uno con su mensaje diciendo <strong>el porqué</strong>, no el qué<br>• Subir poco y seguido en vez de mucho de golpe"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Un error se vuelve una tarde separando lo bueno de lo malo<br>• O se deshace todo, incluido lo que sí servía<br>• Y el mensaje «varios arreglos» no ayuda a nadie dentro de un mes"},"cuidados":{"title":"En este proyecto","info":"• Cada misión sube en <strong>un solo cambio</strong>, con su mensaje largo<br>• Los mensajes cuentan qué falló y qué se aprendió<br>• Son, de hecho, <strong>la bitácora de la asignación 5</strong>"}}};
let labParte='entiendo',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue mirando antes de subir!','¡Muy buen trabajo!','¡Ya distingues funcionar de estar bien!','¡Revisas el cambio y no el archivo!','¡Solo subes lo que puedes explicar!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='⌨️ ¡'+name+' completó la Etapa 4 de la Ruta de la Máquina que Predice (La IA que programa)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

